css:
.px-toggle {
  --px: 0.25rem;
  --w: 6rem;
  --h: 3rem;
  --knob-size: 2.25rem;
  --knob-gap: 0.3rem;

  --c-bg: #1c1c1c;
  --c-face: #252525;
  --c-hi: #3e3e3e;
  --c-sh: #080808;
  --c-pip: #303030;

  --c-on-bg: #001800;
  --c-on-face: #002200;
  --c-on-hi: #004400;
  --c-on-sh: #000;
  --c-on: #39ff14;
  --c-on-dim: #22cc0a;
  --c-on-lo: #0d6604;
  --c-on-glow: rgba(57, 255, 20, 0.38);
  --c-on-glow2: rgba(57, 255, 20, 0.12);

  --bevel-light: rgba(255, 255, 255, 0.08);
  --bevel-dark: rgba(0, 0, 0, 0.7);
  --bevel-size: 0.25rem;

  position: relative;
  display: inline-block;
  width: var(--w);
  height: var(--h);
  cursor: pointer;
  image-rendering: pixelated;
  transition: filter 0.08s steps(2);
}

.px-toggle:hover {
  filter: brightness(1.08);
}

.px-toggle:has(input:active) {
  transform: translate(0.125rem, 0.125rem);
}

.px-toggle input {
  position: absolute;
  inset: 0;
  opacity: 0;
  margin: 0;
  cursor: pointer;
  z-index: 4;
  width: 100%;
  height: 100%;
}

.px-toggle__chassis {
  position: absolute;
  inset: 0;
  background: var(--c-bg);
  box-shadow:
    inset var(--bevel-size) var(--bevel-size) 0 var(--bevel-light),
    inset calc(-1 * var(--bevel-size)) calc(-1 * var(--bevel-size)) 0
      var(--bevel-dark),
    0 0 0 var(--px) var(--c-sh),
    0 var(--px) 0 var(--px) var(--c-sh),
    0 calc(-1 * var(--px)) 0 var(--px) var(--c-hi),
    var(--px) 0 0 var(--px) var(--c-sh),
    calc(-1 * var(--px)) 0 0 var(--px) var(--c-hi),
    calc(var(--px) * 2) calc(var(--px) * 2) 0 0.5rem rgba(0, 0, 0, 0.6);
  transition:
    background 0.08s steps(2),
    box-shadow 0.08s steps(2);
}

.px-toggle__pip {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  left: 0.5rem;
  display: flex;
  flex-direction: column;
  gap: calc(var(--px) * 1.5);
}

.px-toggle__pip span {
  display: flex;
  gap: var(--px);
}

.px-toggle__pip span i {
  display: block;
  width: var(--px);
  height: var(--px);
  background: var(--c-pip);
  transition: background 0.08s steps(2);
}

.px-toggle__knob {
  position: absolute;
  top: 50%;
  left: var(--knob-gap);
  transform: translateY(-50%);
  width: var(--knob-size);
  height: var(--knob-size);
  background: var(--c-face);
  box-shadow:
    inset var(--bevel-size) var(--bevel-size) 0 var(--bevel-light),
    inset calc(-1 * var(--bevel-size)) calc(-1 * var(--bevel-size)) 0
      var(--bevel-dark),
    0 calc(-1 * var(--px)) 0 0 var(--c-hi),
    0 var(--px) 0 0 var(--c-sh),
    calc(-1 * var(--px)) 0 0 0 var(--c-hi),
    var(--px) 0 0 0 var(--c-sh),
    calc(var(--px)) calc(var(--px)) 0 0.2rem rgba(0, 0, 0, 0.5);
  transition:
    left 0.14s steps(6, end),
    background 0.08s steps(2),
    box-shadow 0.08s steps(2);
  z-index: 2;
}

.px-toggle__grid {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
}

.px-toggle__grid::before {
  content: "";
  display: block;
  width: calc(3 * var(--px));
  height: calc(3 * var(--px));
  background: var(--c-hi);
  transition:
    background 0.08s steps(2),
    box-shadow 0.08s steps(2);
  box-shadow:
    calc(2 * var(--px)) 0 0 0 var(--c-hi),
    calc(4 * var(--px)) 0 0 0 var(--c-hi),
    0 calc(2 * var(--px)) 0 0 var(--c-hi),
    calc(2 * var(--px)) calc(2 * var(--px)) 0 0 var(--c-hi),
    calc(4 * var(--px)) calc(2 * var(--px)) 0 0 var(--c-hi),
    0 calc(4 * var(--px)) 0 0 var(--c-hi),
    calc(2 * var(--px)) calc(4 * var(--px)) 0 0 var(--c-hi),
    calc(4 * var(--px)) calc(4 * var(--px)) 0 0 var(--c-hi);
}

.px-toggle input:checked ~ .px-toggle__chassis {
  background: var(--c-on-bg);
  box-shadow:
    inset var(--bevel-size) var(--bevel-size) 0 rgba(57, 255, 20, 0.06),
    inset calc(-1 * var(--bevel-size)) calc(-1 * var(--bevel-size)) 0
      var(--bevel-dark),
    0 0 0 var(--px) var(--c-on-sh),
    0 var(--px) 0 var(--px) var(--c-on-sh),
    0 calc(-1 * var(--px)) 0 var(--px) var(--c-on-hi),
    var(--px) 0 0 var(--px) var(--c-on-sh),
    calc(-1 * var(--px)) 0 0 var(--px) var(--c-on-hi),
    0 0 2.5rem 0.75rem var(--c-on-glow),
    0 0 5rem 1.5rem var(--c-on-glow2),
    calc(var(--px) * 2) calc(var(--px) * 2) 0 0.5rem rgba(0, 0, 0, 0.6);
}

.px-toggle input:checked ~ .px-toggle__pip span i {
  background: var(--c-on-lo);
}

.px-toggle input:checked ~ .px-toggle__knob {
  left: calc(var(--w) - var(--knob-size) - var(--knob-gap));
  background: var(--c-on-face);
  box-shadow:
    inset var(--bevel-size) var(--bevel-size) 0 rgba(57, 255, 20, 0.1),
    inset calc(-1 * var(--bevel-size)) calc(-1 * var(--bevel-size)) 0
      var(--bevel-dark),
    0 calc(-1 * var(--px)) 0 0 var(--c-on-dim),
    0 var(--px) 0 0 var(--c-on-lo),
    calc(-1 * var(--px)) 0 0 0 var(--c-on-dim),
    var(--px) 0 0 0 var(--c-on-lo),
    0 0 1rem 0.4rem var(--c-on-glow),
    calc(var(--px)) calc(var(--px)) 0 0.2rem rgba(0, 0, 0, 0.5);
}

.px-toggle input:checked ~ .px-toggle__knob .px-toggle__grid::before {
  background: var(--c-on);
  box-shadow:
    calc(2 * var(--px)) 0 0 0 var(--c-on),
    calc(4 * var(--px)) 0 0 0 var(--c-on),
    0 calc(2 * var(--px)) 0 0 var(--c-on),
    calc(2 * var(--px)) calc(2 * var(--px)) 0 0 var(--c-on),
    calc(4 * var(--px)) calc(2 * var(--px)) 0 0 var(--c-on),
    0 calc(4 * var(--px)) 0 0 var(--c-on),
    calc(2 * var(--px)) calc(4 * var(--px)) 0 0 var(--c-on),
    calc(4 * var(--px)) calc(4 * var(--px)) 0 0 var(--c-on);
}

.px-toggle input:focus-visible ~ .px-toggle__chassis {
  outline: var(--px) solid var(--c-on);
  outline-offset: calc(2 * var(--px));
}

@media (prefers-reduced-motion: reduce) {
  .px-toggle,
  .px-toggle__knob,
  .px-toggle__chassis,
  .px-toggle__grid::before,
  .px-toggle__pip span i {
    transition: none;
  }
}
